const products={'still-water':{name:'Still Water',notes:'Lavender + bergamot',price:799},'palm-shade':{name:'Palm Shade',notes:'Sandalwood + vetiver',price:799},'first-rain':{name:'First Rain',notes:'Vetiver + mitti',price:799},'discovery-trio':{name:'Discovery Trio',notes:'Three scent discovery set',price:549}};let bag={};try{bag=JSON.parse(localStorage.getItem('oasis-bag')||'{}')}catch{}const drawer=document.querySelector('#bag-drawer'),overlay=document.querySelector('#bag-overlay'),items=document.querySelector('#bag-items');function save(){try{localStorage.setItem('oasis-bag',JSON.stringify(bag))}catch{}render()}function render(){const count=Object.values(bag).reduce((a,b)=>a+b,0);document.querySelectorAll('#bag-count,#drawer-count').forEach(el=>el.textContent=`(${count})`);let total=0;items.innerHTML='';for(const [id,qty] of Object.entries(bag)){if(!products[id]||qty<1)continue;const p=products[id];total+=p.price*qty;const row=document.createElement('div');row.className='bag-row';row.innerHTML=`<div class="bag-thumb"><img src="${location.pathname.includes('/products/')?'../':''}assets/oasis-rollon.png" alt=""></div><div><h3>${p.name}</h3><p>${p.notes}</p><div class="qty"><button type="button" data-qty="${id}" data-change="-1" aria-label="Remove one ${p.name}">−</button><span>${qty}</span><button type="button" data-qty="${id}" data-change="1" aria-label="Add one ${p.name}">+</button></div></div><strong>₹${p.price*qty}</strong>`;items.append(row)}if(!count)items.innerHTML='<p class="bag-empty">Your little oasis awaits.</p>';document.querySelector('#subtotal').textContent=`₹${total.toLocaleString('en-IN')}`}function openBag(){drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');overlay.hidden=false;document.body.style.overflow='hidden';document.querySelector('#bag-close').focus()}function closeBag(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');overlay.hidden=true;document.body.style.overflow=''}document.querySelectorAll('.bag-trigger').forEach(b=>b.addEventListener('click',openBag));document.querySelector('#bag-close').addEventListener('click',closeBag);overlay.addEventListener('click',closeBag);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeBag()});document.addEventListener('click',e=>{const add=e.target.closest('[data-product]');if(add){const id=add.dataset.product;bag[id]=(bag[id]||0)+1;save();openBag()}const qty=e.target.closest('[data-qty]');if(qty){const id=qty.dataset.qty;bag[id]=(bag[id]||0)+Number(qty.dataset.change);if(bag[id]<=0)delete bag[id];save()}});const menu=document.querySelector('.menu-trigger');menu?.addEventListener('click',()=>{const open=document.querySelector('.site-header').classList.toggle('mobile-open');menu.setAttribute('aria-expanded',open)});document.querySelectorAll('.site-header nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.site-header').classList.remove('mobile-open');menu?.setAttribute('aria-expanded','false')}));render();
